function applyDraft(d){document.querySelectorAll('[name=side]').forEach(el=>{el.checked=el.value===d.side});$('quantity').value=d.quantity;$('reason').value=d.reason;$('student-name').value=d.studentName;$('student-id').value=d.studentId;$('learning-notes').value=d.notes;$('reflection').value=d.reflection;}
function saveStatus(message){saveMessage=message;$('save-status').textContent=message;}
function persist(replace=false){try{reconcileReveal(s,state,globalThis.localStorage);if(!store)throw Error('此瀏覽器無法使用本機保存，請匯出 JSON 備份');store.write(makeSave(s,state,dataVersion,draft(),createdAt),{replace});saveBlocked=false;saveStatus('已自動保存於此瀏覽器 · '+new Date().toLocaleTimeString('zh-TW'));return true;}catch(e){saveStatus(/quota|security|storage/i.test(e.message)?'本機保存失敗（空間不足或瀏覽器限制）；請立即匯出 JSON 備份':e.message);return false;}}
function download(text,type,filename){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function syncSettings(){renderIndicatorFields();if(identityVisible(s,state))$('start-year').innerHTML='<option value="all">全部已驗證年份</option>'+[...new Set(data.bars.map(b=>b.date.slice(0,4)))].map(y=>`<option value="${y}">${y}</option>`).join('');$('length').value=String(s.length);$('seed').value=s.seed;$('start-year').value=s.startYear;startOptions();$('start-date').value=s.requestedStartDate??'';}
function startOptions(){if(!identityVisible(s,state)){$('start-date').innerHTML='<option value="">盲測自動選取</option>';$('start-year').innerHTML='<option value="all">全部資料範圍（日期隱藏）</option>';return;}const previous=$('start-date').value;$('start-date').innerHTML='<option value="">自動選取連續區段</option>'+eligibleStarts(data,Number($('length').value),s.warmup===40?40:260,$('start-year').value).map(d=>`<option value="${d}">${d}</option>`).join('');if([...$('start-date').options].some(x=>x.value===previous))$('start-date').value=previous;}
