function clearForm(){$('decision-form').reset();$('quantity').disabled=false;$('error').textContent='';}
function setup(random=false){if(!confirm('開始新回合會取代此瀏覽器的續玩進度與操作筆記。建議先匯出 JSON 備份；原本機存檔會另保留一份上一版。確定繼續？'))return;try{const next=createScenario(data,{seed:random?null:$('seed').value.trim()||null,length:Number($('length').value),startDate:random?null:identityVisible(s,state)?$('start-date').value||null:null,startYear:!random&&identityVisible(s,state)?$('start-year').value:'all',warmup:!random&&identityVisible(s,state)&&s.warmup===40?40:260,excludeStart:s.startDate});s=initializeScenario(next);if(s.requestedStartDate||s.startYear!=='all')revealSession(s,{journal:[]});s.datasetVersion=dataVersion;state=fresh(s);createdAt=new Date().toISOString();clearForm();applyDraft(emptyDraft());syncSettings();$('setup-error').textContent='';render();persist(true);}catch(e){$('setup-error').textContent=e.message;}}
