$('ticker-price').textContent=num(last.close);$('ticker-price').className=tone(m.change);$('ticker-change').textContent=signed(m.change);$('ticker-change').className=tone(m.change);$('ticker-volume').textContent=`${num(last.volume/1000,1)} 千股`;$('ticker-date').textContent=day(last.date);$('equity').className=tone(w-s.initialCash);$('return').className=tone(w-s.initialCash);$('price').className=tone(m.change);
$('data-note').textContent=`真實歷史資料 · 0050 / ${data.bars[0].date}–${data.bars.at(-1).date}，${data.bars.length} 個交易日、${data.events.length} 則官方精選發布 · TWSE 未還原 OHLCV。資產包含已取得的配息權利（未入帳時列應收）；價格只按模擬日已生效分割換算、未還原配息；成交量保留原始股數。新聞含跨年 BLS 原始數據、僅 2024 年 FOMC 決議與少量台積電官方消息；不代表完整當時新聞。`;
