$('scenario-title').textContent=show?s.title:'標的 A · 真實歷史盲測';$('scenario-desc').textContent=show?s.description:`${s.length} 個決策日 · ${s.warmup} 日暖機 · 同種子可重播`;$('clock').textContent=when(v.cutoff)+(state.finished?' · 結算':' · 開盤前');$('round').textContent=`${state.finished?'已完成':'決策日'} ${state.index+1} / ${s.rounds.length}`;$('progress').style.width=`${(state.index+1)/s.rounds.length*100}%`;
$('equity').textContent=money(w);$('return').textContent=`含息權利 ${signed((w/s.initialCash-1)*100)} · 費用 ${money(state.fees)}`;$('cash').textContent=money(state.cash);$('cash').nextElementSibling.textContent=`應收配息 ${money(state.receivable)} · 累計取得 ${money(state.dividends)}`;$('shares').textContent=state.shares.toLocaleString();$('asset').textContent=show?s.asset:'標的 A';$('benchmark').textContent=money(benchmark(s,state));$('price').textContent=`${num(mark(s,state))} TWD`;renderOrderHint();
$('trade-note').textContent='按當日未知開盤價模擬成交。雙向費用 0.1%，不含稅與滑價。除息前持倉取得應收配息，發放日按教學模型於開盤前入現金。跳空導致現金不足會整筆取消並前進；非真實零股撮合規則。';
$('ohlc').innerHTML=`<b>${day(last.date)} 已完成日線${last.splitFactor!==1?'（依當時已生效分割換算價格）':''}</b><span>開 ${num(last.open)}</span><span>高 ${num(last.high)}</span><span>低 ${num(last.low)}</span><span>收 ${num(last.close)}</span><span>量 ${num(last.volume,0)} 股（原始量）</span>${(r.splitRatio??1)!==1?'<b>本日分割：單位 ×'+r.splitRatio+'，昨收參考等比例換算</b>':''}`;
$('range').textContent=`最近 ${Math.min(60,v.bars.length)} 根日 K · 價格按已生效分割換算 / 量為原始股數`;chart(v.bars);
const cards=[['5 日 / 20 日均線',`${num(m.sma5)} / ${num(m.sma20)}`,'收盤價簡單平均'],['單日 / 20 日漲跌',`<span class="${tone(m.change)}">${signed(m.change)}</span> / <span class="${tone(m.return20)}">${signed(m.return20)}</span>`,'分割可比價，未還原配息'],['20 日年化波動',`${num(m.volatility20)}%`,'日對數報酬樣本標準差 × √252'],['20 日高 / 低',`${num(m.high20)} / ${num(m.low20)}`,'包含最後已完成交易日'],['等值量 / 20 日均量',`${num(m.volumeRatio)} 倍`,`${num((last.comparableVolume??last.volume)/1000,1)} 等值千股 / ${num(m.meanVolume/1000,1)} 千股`],['全日成交金額',`${num(last.turnover/1e8)} 億`,`${num(last.trades,0)} 筆成交 · 非盤中即時值`]];
const latest=calculateIndicators(v.bars,s.indicatorSettings).latest;cards.splice(0,1);for(const [key,title] of [['sma','SMA'],['ema','EMA'],['bbMiddle','布林中軌'],['bbUpper','布林上軌'],['bbLower','布林下軌'],['rsi','RSI'],['macd','MACD'],['macdSignal','MACD 訊號'],['macdHistogram','MACD 柱值'],['k','KD · K'],['d','KD · D'],['volumeMA','等值量均線']]){const enabled=key.startsWith('bb')?s.indicatorSettings.bbEnabled:key.startsWith('macd')?s.indicatorSettings.macdEnabled:['k','d'].includes(key)?s.indicatorSettings.kdEnabled:s.indicatorSettings[key+'Enabled'];if(enabled)cards.push([title,num(latest[key]),`僅使用已完成日線 · 最少暖機 ${requiredWarmup(s.indicatorSettings)} 根`]);}
$('indicators').innerHTML=cards.map(([title,value,note])=>`<div class="indicator"><span>${title}</span><strong>${value}</strong><small>${note}</small></div>`).join('');
$('news-count').textContent=`${v.news.length} 則已發布`;
$('macro').innerHTML='<div>新聞僅依當時可見時間提供；盲測保留原始統計值，隱藏日期、標的名稱及連結。</div>';
$('news').innerHTML=v.news.length?v.news.map(raw=>{const n=newsView(s,state,raw);return `<article class="news-item"><time>${show?date(raw.availableAt??raw.publishedAt):n.availableAt} · 已發布資訊</time><h3>${esc(n.title)}</h3><p>${esc(n.body)}${n.vintageNote?'（'+esc(n.vintageNote)+'）':''}</p>${show?`<a class="source" href="${esc(n.url)}" target="_blank" rel="noopener">${esc(n.source)} · 原始公告 ↗</a>`:`<span class="source">${esc(n.source)}</span>`}</article>`;}).join(''):'<div class="empty">截至此刻，資料庫沒有已發布的精選公告。這不代表當時沒有其他新聞。</div>';
$('journal').innerHTML=state.journal.length?[...state.journal].reverse().map(j=>`<article class="journal-item"><b>${when(j.at)} · <span class="side-badge side-${j.side}">${labels[j.side]}</span> ${j.quantity?j.quantity+' 單位':''}</b><p>${esc(j.reason)}</p><small>${j.status==='cancelled'?'開盤跳空，現金不足，訂單取消':j.side==='hold'?'未交易':`開盤成交 ${num(j.price)} · 費用 ${money(j.fee)}`} · 當日收盤 ${num(j.close)}</small></article>`).join(''):'<div class="empty">還沒有決策。<br>先看 K 線與資訊，再寫下判斷。</div>';
$('game-status').textContent=state.finished?`回合完成。總資產 ${money(w)}，報酬 ${num((w/s.initialCash-1)*100)}%。`:`第 ${state.index+1} / ${s.rounds.length} 個決策日，市場時間 ${when(v.cutoff)}，總資產 ${money(w)}。${state.journal.at(-1)?.status==='cancelled'?'上一筆委託因現金不足取消。':''}`;
$('inline-trade-link').href=state.finished?'#review':'#decision-form';$('inline-trade-link').textContent=state.finished?'查看結算 →':'前往委託 →';$('mobile-trade-link').href=state.finished?'#review':'#decision-form';$('mobile-trade-link').textContent=state.finished?'查看回合結算':'前往交易 →';
$('decision-form').hidden=state.finished;$('complete').hidden=!state.finished;$('review').hidden=!state.finished;if(state.finished)review(w,v);else $('review').innerHTML='';
