function review(w,v){const ret=(w/s.initialCash-1)*100,bret=(benchmark(s,state)/s.initialCash-1)*100;let peak=s.initialCash,dd=0;state.equity.forEach(x=>{peak=Math.max(peak,x);dd=Math.max(dd,(peak-x)/peak)});const sources=[...new Set(v.bars.map(b=>b.sourceUrl))];$('review').innerHTML=`<span class="eyebrow">結果揭曉，思考繼續</span><h2>你完成了一段真實市場旅程。</h2><div class="review-grid"><div>你的含息權利報酬<strong class="${tone(ret)}">${signed(ret)}</strong></div><div>相對買入持有<strong class="${tone(ret-bret)}">${ret-bret>0?'+':''}${num(ret-bret)} 個百分點</strong></div><div>收盤資產最大回撤<strong class="${dd>0?'down':'neutral'}">${dd>0?'−':''}${num(dd*100)}%</strong></div></div><p>種子 ${esc(s.seed)} · 起點年份設定 ${esc(s.startYear)} · ${s.startDate} 開始 · ${s.length} 個決策日。最後持倉按收盤價估值，未強制清算；包含已取得的應收配息與已入帳配息，不再投資、不含稅。</p><ol><li>哪次決策同時考慮了價格、成交量與當時資訊？</li><li>公告發布後，下一次開盤是否已反映消息？</li><li>換一個起點，策略是否仍合理？一回合績效不證明策略有效。</li></ol><p>日資料包含全日成交量，最後結算以後續交易日 08:55 作為保守可見時間，不是假稱 13:30 即有完整成交量。K 線按當時已生效分割換算；分割同步換算持倉，除息另透過配息權利加入資產。未驗證券商實際入帳時刻，教學模型以發放日開盤前入現金。這是獨立教育用事實整理，非來源機構背書；來源、加工方式與條款不確定性見頁尾說明。</p><p>${sources.map((u,i)=>`<a class="review-source" href="${esc(u)}" target="_blank" rel="noopener">TWSE 原始月份資料 ${i+1} ↗</a>`).join(' · ')}</p>`;}
function chart(all){const study=calculateIndicators(all,s.indicatorSettings),model=chartModel(all),bars=model.bars,tail=key=>study.series[key].slice(-bars.length),priceKeys=['sma','ema','bbMiddle','bbUpper','bbLower'],pricePoints=[...bars.flatMap(b=>[b.low,b.high]),...priceKeys.flatMap(tail)].filter(Number.isFinite),min=Math.min(...pricePoints),max=Math.max(...pricePoints),pad=(max-min)*.08||1,lo=min-pad,hi=max+pad,W=640,H=340,left=45,right=12,top=15,priceBottom=215,volTop=245,bottom=310,step=(W-left-right)/bars.length,bw=Math.max(2,step*.65);const y=p=>priceBottom-(p-lo)/(hi-lo)*(priceBottom-top),x=i=>left+step*(i+.5),maxVol=Math.max(...bars.map(b=>b.volume),1);const grid=[0,1,2,3].map(i=>{const p=lo+(hi-lo)*i/3;return `<line x1="${left}" y1="${y(p)}" x2="${W-right}" y2="${y(p)}" stroke="#29394e"/><text x="0" y="${y(p)+4}" font-size="10" fill="#8ca1bc">${p.toFixed(1)}</text>`}).join('');const candles=bars.map((b,i)=>{const color=b.close>b.open?'#f27981':b.close<b.open?'#45cda4':'#a6b4c8',body=Math.max(Math.abs(y(b.open)-y(b.close)),1.5),vy=bottom-b.volume/maxVol*(bottom-volTop);return `<g><title>${identityVisible(s,state)?b.date:relativeDay(s,b.date)} 換算開${b.open} 高${b.high} 低${b.low} 收${b.close}；原始收${b.rawClose??b.close} 量${b.volume}股</title><line clip-path="url(#price-clip)" x1="${x(i)}" y1="${y(b.high)}" x2="${x(i)}" y2="${y(b.low)}" stroke="${color}"/><rect clip-path="url(#price-clip)" x="${x(i)-bw/2}" y="${Math.min(y(b.open),y(b.close))}" width="${bw}" height="${body}" fill="${color}"/><rect x="${x(i)-bw/2}" y="${vy}" width="${bw}" height="${bottom-vy}" fill="${color}" opacity=".65"/></g>`}).join('');const ma=n=>(n===5?model.ma5:model.ma20).map((value,i)=>value==null?null:`${x(i)},${y(value)}`).filter(Boolean).join(' ');const dates=[0,Math.floor((bars.length-1)/2),bars.length-1].map(i=>`<text x="${x(i)}" y="330" text-anchor="middle" font-size="10" fill="#8ca1bc">${identityVisible(s,state)?bars[i].date.slice(5):relativeDay(s,bars[i].date)}</text>`).join('');$('chart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${bars.length} 根歷史 K 線及對齊成交量，最後日期 ${identityVisible(s,state)?bars.at(-1).date:relativeDay(s,bars.at(-1).date)}"><defs><clipPath id="price-clip"><rect x="${left}" y="${top}" width="${W-left-right}" height="${priceBottom-top}"/></clipPath></defs>${grid}${candles}<polyline clip-path="url(#price-clip)" points="${tail('sma').map((v,i)=>v==null?null:`${x(i)},${y(v)}`).filter(Boolean).join(' ')}" fill="none" stroke="#e0ba71" stroke-width="1.5"/><polyline clip-path="url(#price-clip)" points="${tail('ema').map((v,i)=>v==null?null:`${x(i)},${y(v)}`).filter(Boolean).join(' ')}" fill="none" stroke="#79aaff" stroke-width="1.5"/><line x1="${left}" y1="233" x2="${W-right}" y2="233" stroke="#29394e"/><text x="0" y="253" font-size="9" fill="#8ca1bc">成交量</text><text x="0" y="266" font-size="8" fill="#8ca1bc">${num(maxVol/1e6,1)}M</text>${dates}${['bbMiddle','bbUpper','bbLower'].map(key=>`<polyline clip-path="url(#price-clip)" points="${tail(key).map((v,i)=>v==null?null:`${x(i)},${y(v)}`).filter(Boolean).join(' ')}" fill="none" stroke="#be8af0" stroke-width="1"/>`).join('')}<text x="${W-260}" y="12" font-size="9" fill="#a6b4c8">${s.indicatorSettings.smaEnabled?'SMA'+s.indicatorSettings.smaPeriod+' ':''}${s.indicatorSettings.emaEnabled?'EMA'+s.indicatorSettings.emaPeriod+' ':''}${s.indicatorSettings.bbEnabled?'布林'+s.indicatorSettings.bbPeriod+'×'+s.indicatorSettings.bbDeviations:''}</text></svg>`;$('chart').innerHTML+=indicatorPanels(study,bars);$('chart').scrollLeft=$('chart').scrollWidth;}
$('decision-form').addEventListener('submit',e=>{e.preventDefault();try{state=decide(s,state,new FormData(e.target).get('side'),Number($('quantity').value),$('reason').value);$('reason').value='';$('error').textContent='';render();persist();if(state.finished)$('complete-title').focus?.();}catch(e){$('error').textContent=e.message;}});
