$('export-report').addEventListener('click',async()=>{const button=$('export-report');if(button.disabled)return;button.disabled=true;button.textContent='正在製作 PDF…';saveStatus('正在載入 PDF 字型並排版，首次匯出可能需要較久。');try{const reportState=structuredClone(state),reportScenario=structuredClone(s),reportDraft={...draft(),generatedAt:new Date().toISOString()};const bytes=await performancePdf(reportScenario,reportState,reportDraft);download(bytes,'application/pdf',reportFilename(reportScenario,reportState));saveStatus('PDF 已產生並交由瀏覽器下載。');}catch(e){saveStatus('PDF 匯出失敗：'+e.message+'。進度與筆記仍保留，可重試。');}finally{button.disabled=false;button.textContent='下載投資績效報告（PDF）';}});
$('backup-original').addEventListener('click',()=>{const raw=store?.raw();if(raw)download(raw,'application/json','market-replay-original-save.json');else saveStatus('沒有可下載的原存檔');});
$('backup-previous').addEventListener('click',()=>{try{const raw=store?.previous();if(raw)download(raw,'application/json','market-replay-previous-save.json');else saveStatus('沒有上一版本機存檔');}catch(e){saveStatus('無法讀取上一版本機存檔');}});
$('import-save').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>2000000)throw Error('備份檔過大');const raw=await file.text(),loaded=restoreSave(raw,data,dataVersion);if(!confirm('載入這份備份會取代目前畫面進度。請先匯出目前 JSON；原本機存檔會另保留一份上一版。確定載入？'))return;s=loaded.s;state=loaded.state;createdAt=loaded.createdAt;try{reconcileReveal(s,state,globalThis.localStorage);}catch(e){saveStatus(e.message);}applyDraft(loaded.draft);syncSettings();$('error').textContent='';render();persist(true);}catch(err){saveStatus('載入失敗：'+err.message+'。目前進度與原存檔保留。');}finally{e.target.value='';}});
['quantity','reason','student-name','student-id','learning-notes','reflection'].forEach(id=>$(id).addEventListener('input',()=>persist()));
$('length').addEventListener('change',startOptions);$('start-year').addEventListener('change',startOptions);$('apply-setup').addEventListener('click',()=>setup(false));$('random-start').addEventListener('click',()=>setup(true));$('start-year').innerHTML='<option value="all">全部資料範圍</option>';startOptions();syncSettings();if(restored){applyDraft(restored.draft);}render();saveStatus(saveMessage);if(!saveBlocked&&!restored)persist();

if(typeof ResizeObserver!=='undefined'){const portfolioObserver=new ResizeObserver(entries=>{document.documentElement.style.setProperty('--portfolio-height',`${Math.ceil(entries[0].target.getBoundingClientRect().height)}px`);});portfolioObserver.observe($('portfolio-strip'));}

function revealIdentity(){if(identityVisible(s,state))return true;if(!confirm('揭露真實標的與日期？本回合將永久標記「曾主動揭露」，報告與備份均會記錄；此操作無法還原。'))return false;revealSession(s,state);persist();syncSettings();render();return true;}
$('reveal-identity').addEventListener('click',revealIdentity);
$('source-notice-link').addEventListener('click',e=>{if(!identityVisible(s,state)&&!revealIdentity())e.preventDefault();});

function renderIndicatorFields(){const cfg=s.indicatorSettings??defaultIndicatorSettings();const names={sma:'SMA',ema:'EMA',bb:'布林通道',rsi:'RSI',macd:'MACD',kd:'KD',volumeMA:'成交量均線'},fieldNames={Period:'週期',Deviations:'標準差倍數',Fast:'快線',Slow:'慢線',Signal:'訊號週期',Lookback:'回看週期',KSmoothing:'K 平滑',DSmoothing:'D 平滑'};$('indicator-fields').innerHTML=Object.entries(names).map(([group,label])=>`<fieldset><legend><label><input type="checkbox" name="${group}Enabled" ${cfg[group+'Enabled']?'checked':''}> ${label}</label></legend>${Object.keys(cfg).filter(k=>k.startsWith(group)&&!k.endsWith('Enabled')).map(k=>`<label>${fieldNames[k.slice(group.length)]??k}<input type="number" name="${k}" value="${cfg[k]}" min="${k==='bbDeviations'?.1:k.includes('Smoothing')?1:2}" max="${k==='bbDeviations'?5:120}" step="${k==='bbDeviations'?.1:1}" required></label>`).join('')}</fieldset>`).join('');}
function indicatorPanels(study,bars){const cfg=s.indicatorSettings,groups=[['RSI',['rsi'],cfg.rsiEnabled],['MACD / 訊號 / 柱值',['macd','macdSignal','macdHistogram'],cfg.macdEnabled],['KD',['k','d'],cfg.kdEnabled],['分割等值量均線',['volumeMA'],cfg.volumeMAEnabled]];return groups.filter(g=>g[2]).map(([label,keys])=>{const lines=keys.map(k=>study.series[k].slice(-bars.length)),values=lines.flat().filter(Number.isFinite),floor=label==='RSI'||label==='KD'?0:Math.min(0,...values),ceiling=label==='RSI'||label==='KD'?100:Math.max(1,...values),y=v=>104-(v-floor)/(ceiling-floor)*76,x=i=>45+(583/bars.length)*(i+.5);return `<svg class="indicator-panel" viewBox="0 0 640 120" role="img" aria-label="${label}，僅已完成交易日"><text x="10" y="15" fill="#a6b4c8" font-size="11">${label}${values.length?'':' · 資料不足'}</text><text x="0" y="35" fill="#8ca1bc" font-size="9">${num(ceiling,1)}</text><text x="0" y="106" fill="#8ca1bc" font-size="9">${num(floor,1)}</text><line x1="45" y1="104" x2="628" y2="104" stroke="#29394e"/>${lines.map((line,j)=>`<polyline points="${line.map((v,i)=>v==null?null:`${x(i)},${y(v)}`).filter(Boolean).join(' ')}" fill="none" stroke="${['#e0ba71','#79aaff','#be8af0'][j]}" stroke-width="1.5"/>`).join('')}</svg>`;}).join('');}
$('indicator-form').addEventListener('submit',e=>{e.preventDefault();try{const form=new FormData(e.target),cfg=Object.fromEntries(Object.keys(defaultIndicatorSettings()).map(k=>[k,k.endsWith('Enabled')?form.has(k):Number(form.get(k))])),next=normalizeIndicatorSettings(cfg);setIndicatorSettings(s,state,next);$('indicator-error').textContent=`已記錄：完成 ${state.journal.length} 筆決策後套用${state.finished?'（僅供回顧）':'，自第 '+(state.journal.length+1)+' 筆決策生效'}`;render();persist();}catch(err){$('indicator-error').textContent=err.message;}});
